#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyTypeClass {
    // Base categories
    BooleanType,
    IntegerType,
    FloatingType,
    ComplexType,
    NumberType,
    InexactType,
    ScalarType,
    ObjectType,
    // Integer leaves
    Int8Type,
    Int16Type,
    Int32Type,
    Int64Type,
    UInt8Type,
    UInt16Type,
    UInt32Type,
    UInt64Type,
    // Floating leaves
    Float32Type,
    Float64Type,
    // Complex leaves
    Complex64Type,
    Complex128Type,
}

pub fn issubclass_(arg1: NumpyTypeClass, arg2: NumpyTypeClass) -> bool {
    // Reflexivity
    if arg1 == arg2 {
        return true;
    }

    match (arg1, arg2) {
        // Integer leaves → IntegerType
        (NumpyTypeClass::Int8Type,  NumpyTypeClass::IntegerType) |
        (NumpyTypeClass::Int16Type, NumpyTypeClass::IntegerType) |
        (NumpyTypeClass::Int32Type, NumpyTypeClass::IntegerType) |
        (NumpyTypeClass::Int64Type, NumpyTypeClass::IntegerType) |
        (NumpyTypeClass::UInt8Type, NumpyTypeClass::IntegerType) |
        (NumpyTypeClass::UInt16Type,NumpyTypeClass::IntegerType) |
        (NumpyTypeClass::UInt32Type,NumpyTypeClass::IntegerType) |
        (NumpyTypeClass::UInt64Type,NumpyTypeClass::IntegerType) => true,

        // Floating leaves → FloatingType
        (NumpyTypeClass::Float32Type, NumpyTypeClass::FloatingType) |
        (NumpyTypeClass::Float64Type, NumpyTypeClass::FloatingType) => true,

        // Complex leaves → ComplexType
        (NumpyTypeClass::Complex64Type,  NumpyTypeClass::ComplexType) |
        (NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType) => true,

        // Mid‐level relations
        (NumpyTypeClass::IntegerType,  NumpyTypeClass::NumberType) => true,
        (NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType) |
        (NumpyTypeClass::FloatingType, NumpyTypeClass::NumberType) => true,
        (NumpyTypeClass::ComplexType,  NumpyTypeClass::InexactType) |
        (NumpyTypeClass::ComplexType,  NumpyTypeClass::NumberType) => true,

        // Top‐level scalar relations
        (NumpyTypeClass::NumberType,   NumpyTypeClass::ScalarType) |
        (NumpyTypeClass::BooleanType,  NumpyTypeClass::ScalarType) |
        (NumpyTypeClass::IntegerType,  NumpyTypeClass::ScalarType) |
        (NumpyTypeClass::FloatingType, NumpyTypeClass::ScalarType) |
        (NumpyTypeClass::ComplexType,  NumpyTypeClass::ScalarType) |
        (NumpyTypeClass::InexactType,  NumpyTypeClass::ScalarType) => true,

        // Everything else is not a direct subclass
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_reflexivity() {
        for &ty in &[
            NumpyTypeClass::BooleanType,
            NumpyTypeClass::IntegerType,
            NumpyTypeClass::FloatingType,
            NumpyTypeClass::ComplexType,
            NumpyTypeClass::NumberType,
            NumpyTypeClass::InexactType,
            NumpyTypeClass::ScalarType,
            NumpyTypeClass::ObjectType,
            NumpyTypeClass::Int8Type,
            NumpyTypeClass::UInt64Type,
            NumpyTypeClass::Float32Type,
            NumpyTypeClass::Complex128Type,
        ] {
            assert!(issubclass_(ty, ty));
        }
    }

    #[test]
    fn test_integer_leaves() {
        let leaves = [
            NumpyTypeClass::Int8Type,
            NumpyTypeClass::Int16Type,
            NumpyTypeClass::Int32Type,
            NumpyTypeClass::Int64Type,
            NumpyTypeClass::UInt8Type,
            NumpyTypeClass::UInt16Type,
            NumpyTypeClass::UInt32Type,
            NumpyTypeClass::UInt64Type,
        ];
        for &leaf in &leaves {
            assert!(issubclass_(leaf, NumpyTypeClass::IntegerType));
            assert!(!issubclass_(leaf, NumpyTypeClass::NumberType)); // no transitive
        }
    }

    #[test]
    fn test_floating_and_complex_leaves() {
        assert!(issubclass_(NumpyTypeClass::Float32Type, NumpyTypeClass::FloatingType));
        assert!(issubclass_(NumpyTypeClass::Float64Type, NumpyTypeClass::FloatingType));
        assert!(issubclass_(NumpyTypeClass::Complex64Type, NumpyTypeClass::ComplexType));
        assert!(issubclass_(NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType));

        // No unintended relations
        assert!(!issubclass_(NumpyTypeClass::Float32Type, NumpyTypeClass::NumberType));
        assert!(!issubclass_(NumpyTypeClass::Complex64Type, NumpyTypeClass::NumberType));
    }

    #[test]
    fn test_mid_and_top_levels() {
        // Mid‐level
        assert!(issubclass_(NumpyTypeClass::IntegerType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType));
        assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::ComplexType, NumpyTypeClass::InexactType));
        assert!(issubclass_(NumpyTypeClass::ComplexType, NumpyTypeClass::NumberType));

        // Top‐level
        let top_leaves = [
            NumpyTypeClass::NumberType,
            NumpyTypeClass::BooleanType,
            NumpyTypeClass::IntegerType,
            NumpyTypeClass::FloatingType,
            NumpyTypeClass::ComplexType,
            NumpyTypeClass::InexactType,
        ];
        for &leaf in &top_leaves {
            assert!(issubclass_(leaf, NumpyTypeClass::ScalarType));
        }

        // No transitive hop
        assert!(!issubclass_(NumpyTypeClass::Int32Type, NumpyTypeClass::ScalarType));
        assert!(!issubclass_(NumpyTypeClass::Float32Type, NumpyTypeClass::ScalarType));
    }

    #[test]
    fn test_object_type() {
        // Only itself
        assert!(issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ObjectType));
        assert!(!issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ScalarType));
        assert!(!issubclass_(NumpyTypeClass::Int8Type, NumpyTypeClass::ObjectType));
    }
}